CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE retailers(slug text PRIMARY KEY,name text NOT NULL,url text NOT NULL,enabled boolean NOT NULL,notice text,next_due timestamptz);
CREATE TABLE sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),retailer text NOT NULL REFERENCES retailers(slug),external_id text NOT NULL,name text NOT NULL,url text NOT NULL,scope text NOT NULL CHECK(scope IN ('branch','retailer')),meta jsonb NOT NULL,active boolean NOT NULL DEFAULT true,discovered_at timestamptz NOT NULL DEFAULT now(),last_success timestamptz,published_at timestamptz,published_run uuid,row_count integer NOT NULL DEFAULT 0,UNIQUE(retailer,external_id));
CREATE TABLE runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN ('discover','catalog','match')),retailer text REFERENCES retailers(slug),source_id uuid REFERENCES sources(id),parent_id uuid REFERENCES runs(id),scheduled_for timestamptz,status text NOT NULL CHECK(status IN ('pending','queued','running','success','failed','quarantined','superseded')),attempts integer NOT NULL DEFAULT 0,checkpoint jsonb NOT NULL DEFAULT '{}',summary jsonb NOT NULL DEFAULT '{}',error text,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,finished_at timestamptz);
CREATE UNIQUE INDEX run_occurrence ON runs(retailer,scheduled_for) WHERE kind='discover' AND scheduled_for IS NOT NULL;
CREATE INDEX runs_pending ON runs(status,created_at);
CREATE TABLE staging(run_id uuid NOT NULL REFERENCES runs(id) ON DELETE CASCADE,key text NOT NULL,data jsonb NOT NULL,PRIMARY KEY(run_id,key));
CREATE TABLE artifacts(source_id uuid PRIMARY KEY REFERENCES sources(id),run_id uuid NOT NULL REFERENCES runs(id),content text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,normalized_name text NOT NULL,attributes jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_search ON products USING gin(normalized_name gin_trgm_ops);
CREATE TABLE listings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),retailer text NOT NULL REFERENCES retailers(slug),namespace text NOT NULL,external_key text NOT NULL,name text NOT NULL,description text,category text,gtin text,raw jsonb NOT NULL,identity_hash text NOT NULL,normalized_name text NOT NULL,attributes jsonb NOT NULL,product_id uuid NOT NULL REFERENCES products(id),match_status text NOT NULL CHECK(match_status IN ('separate','matched')),matched_hash text,next_match_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(retailer,namespace,external_key));
CREATE INDEX listings_search ON listings USING gin(normalized_name gin_trgm_ops);
CREATE INDEX listings_match ON listings(next_match_at);
CREATE INDEX listings_product ON listings(product_id);
CREATE TABLE offers(source_id uuid NOT NULL REFERENCES sources(id),listing_id uuid NOT NULL REFERENCES listings(id),price numeric(14,2) NOT NULL CHECK(price>=0),regular_price numeric(14,2),promo_price numeric(14,2),unit_price text,available boolean,promotion text,source_updated_at timestamptz,retrieved_at timestamptz NOT NULL,run_id uuid NOT NULL REFERENCES runs(id),PRIMARY KEY(source_id,listing_id));
CREATE TABLE match_decisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid NOT NULL REFERENCES listings(id),identity_hash text NOT NULL,product_id uuid REFERENCES products(id),method text NOT NULL,probability numeric,evidence jsonb NOT NULL,model text,prompt_version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai_cache(key text PRIMARY KEY,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai_usage(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_id uuid REFERENCES runs(id),endpoint text NOT NULL,model text NOT NULL,status text NOT NULL,input_tokens integer NOT NULL,output_tokens integer NOT NULL,cost_usd numeric(18,8) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE logs(id uuid PRIMARY KEY,level text NOT NULL,message text NOT NULL,process text,correlation_id text,run_id text,retailer text,source_id text,data jsonb,error jsonb,created_at timestamptz NOT NULL);
CREATE INDEX logs_filter ON logs(created_at DESC,level);
CREATE INDEX logs_correlation ON logs(correlation_id);
CREATE TABLE login_attempts(key text PRIMARY KEY,attempts integer NOT NULL,window_start timestamptz NOT NULL);
CREATE TABLE host_limits(host text PRIMARY KEY,next_at timestamptz NOT NULL);
